set -uo pipefail
# shellcheck source=lib/validate-lib.sh
source "$(dirname "${BASH_SOURCE[0]}")/lib/validate-lib.sh" TIER="$(tier_or_die "${1:-quick}")" # --- quick ----------------------------------------------------------------- assert "packaging metadata present" \ 'set -- $(ls pyproject.toml */pyproject.toml 2>/dev/null) [ "$#" -gt 0 ] || { echo "no pyproject.toml anywhere"; exit 1; }' check "pyproject parses" "python3" \ 'python3 - <<PY
import glob, sys
try: import tomllib
except ModuleNotFoundError: sys.exit(77)
for f in glob.glob("pyproject.toml") + glob.glob("*/pyproject.toml"): tomllib.load(open(f, "rb"))
PY' # Every make target here depends on INSTALL_STAMP, which rebuilds the venv. A
# missing or half-built .venv makes lint/typecheck/test exit 2 for a reason that
# has nothing to do with the code — BLOCKED, not FAIL.
venv_ready { [ -x .venv/bin/python ]; } if venv_ready; then check "lint" "make" 'make lint' check "typecheck" "make" 'make typecheck'
else block "lint" "not run; .venv/bin/python missing or venv half-built — run: make setup" block "typecheck" "not run; .venv/bin/python missing or venv half-built — run: make setup"
fi [ "$TIER" = "quick" ] && { report "$TIER"; exit $?; } # --- full ------------------------------------------------------------------ if venv_ready; then check "test suite" "make" 'make test'
else block "test suite" "not run; .venv/bin/python missing — run: make setup"
fi report "$TIER"
